{"content": "// CSV exporter.
// Exports tasks as CSV for admin users only; records an audit entry.

import { taskManager } from './tasks.js';
import { canExport } from './permissions.js';
import { record } from './audit.js';

/** Escape a single CSV field value per RFC 4180. */
function escapeCsvField(value: string): string {
  if (
    value.includes(',') ||
    value.includes('"') ||
    value.includes('\n') ||
    value.includes('\r')
  ) {
    return '"' + value.replace(/"/g, '""') + '"';
  }
  return value;
}

export function exportTasks(userId: string): string {
  if (!canExport(userId)) {
    throw new Error(`User '${userId}' is not authorized to export tasks`);
  }

  const tasks = taskManager.listAll();
  const header = ['id', 'title', 'status', 'assignee', 'createdAt'];
  const lines: string[] = [header.join(',')];

  for (const task of tasks) {
    const row = [
      escapeCsvField(task.id),
      escapeCsvField(task.title),
      escapeCsvField(task.status),
      escapeCsvField(task.assignee),
      escapeCsvField(String(task.createdAt)),
    ];
    lines.push(row.join(','));
  }

  record({
    action: 'export',
    userId,
    details: `Exported ${tasks.length} task(s)`,
    timestamp: Date.now(),
  });

  return lines.join('\n') + '\n';
}
