{"content": "// Task CRUD and status transitions.
// Validates inputs, enforces status machine, checks permissions,
// integrates with cache and audit log.

import { findById, validateExists } from './users.js';
import { canDelete } from './permissions.js';
import { record } from './audit.js';

export type Task = {
  id: string;
  title: string;
  description: string;
  status: 'open' | 'in_progress' | 'done';
  createdBy: string;
  assignee: string;
  createdAt: number;
};

/** Valid status transitions: open -> in_progress -> done. */
type StatusTransitionMap = Record<string, string[]>;

const STATUS_TRANSITIONS: StatusTransitionMap = {
  open: ['in_progress'],
  in_progress: ['done'],
  done: [],
};

class TaskManager {
  private tasks = new Map<string, Task>();
  private cache: { invalidate: (key: string) => void } | null = null;

  /** Inject a cache instance so status changes can invalidate stale entries. */
  setCache(cache: { invalidate: (key: string) => void }) {
    this.cache = cache;
  }

  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
    if (!input.title.trim()) {
      throw new Error('Task title must not be empty');
    }
    // Ensure both users exist.
    validateExists(input.createdBy);
    validateExists(input.assignee);

    const task: Task = {
      ...input,
      id: Math.random().toString(36).slice(2),
      createdAt: Date.now(),
    };
    this.tasks.set(task.id, task);

    record({
      action: 'create',
      userId: input.createdBy,
      taskId: task.id,
      details: `Created task '${task.title}'`,
      timestamp: Date.now(),
    });

    return task;
  }

  getTask(id: string): Task | null {
    return this.tasks.get(id) ?? null;
  }

  updateStatus(id: string, newStatus: Task['status']): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    const allowed = STATUS_TRANSITIONS[task.status] ?? [];
    if (!allowed.includes(newStatus)) {
      throw new Error(
        `Invalid status transition: '${task.status}' -> '${newStatus}'`,
      );
    }

    task.status = newStatus;

    this.cache?.invalidate(id);

    record({
      action: 'status_change',
      userId: task.createdBy,
      taskId: id,
      details: `Status changed to '${newStatus}'`,
      timestamp: Date.now(),
    });

    return task;
  }

  delete(id: string, userId: string): boolean {
    const task = this.tasks.get(id);
    if (!task) return false;

    if (!canDelete(task, userId)) {
      return false;
    }

    this.tasks.delete(id);
    this.cache?.invalidate(id);

    record({
      action: 'delete',
      userId,
      taskId: id,
      details: `Deleted task '${task.title}'`,
      timestamp: Date.now(),
    });

    return true;
  }

  listByUser(userId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (t) => t.assignee === userId || t.createdBy === userId,
    );
