{"content": "// In-memory cache with TTL.
// get() returns null on miss or expiry; invalidate() removes a key.

type CacheEntry<T> = { value: T; expiresAt: number };

/** Shared cache instance used by taskManager so tests and the manager share state. */
export const taskCache = new Cache();

export class Cache {
  private store = new Map<string, CacheEntry<unknown>>();

  set<T>(key: string, value: T, ttlMs: number) {
    this.store.set(key, { value, expiresAt: Date.now() + ttlMs });
  }

  get<T>(key: string): T | null {
    const entry = this.store.get(key);
    if (!entry) return null;
    if (Date.now() > entry.expiresAt) {
      this.store.delete(key);
      return null;
    }
    return entry.value as T;
  }

  invalidate(key: string) {
    this.store.delete(key);
  }
}
