1	// Task CRUD and status transitions.
2	// Validates inputs, enforces status machine, checks permissions,
3	// integrates with cache and audit log.
4	
5	import { findById } from './users.js';
6	import { canDelete } from './permissions.js';
7	import { record } from './audit.js';
8	import { Cache } from './cache.js';
9	export type Task = {
10	  id: string;
11	  title: string;
12	  description: string;
13	  status: 'open' | 'in_progress' | 'done';
14	  createdBy: string;
15	  assignee: string;
16	  createdAt: number;
17	};
18	
19	/** Valid status transitions: open -> in_progress -> done. */
20	type StatusTransitionMap = Record<string, string[]>;
21	
22	const STATUS_TRANSITIONS: StatusTransitionMap = {
23	  open: ['in_progress'],
24	  in_progress: ['done'],
25	  done: [],
26	};
27	
28	class TaskManager {
29	  private tasks = new Map<string, Task>();
30	  private cache: Cache | null = null;
31	
32	  /** Attach a Cache instance so status changes and deletes can invalidate entries. */
33	  setCache(cache: Cache) {
34	    this.cache = cache;
35	  }
36	
37	  create(input: Omit<Task, 'id' | 'createdAt'>): Task {
38	    if (!input.title.trim()) {
39	      throw new Error('Task title must not be empty');
40	    }
41	    // Validate user existence inline to avoid circular ESM dependency
42	    // (index.ts → tasks.ts → users.ts would deadlock at module-init time
43	    // if tasks.ts imported validateExists eagerly).
44	    const ensureUserExists = (userId: string) => {
45	      if (!findById(userId)) {
46	        throw new Error(`User '${userId}' does not exist`);
47	      }
48	    };
49	    ensureUserExists(input.createdBy);
50	    ensureUserExists(input.assignee);
51	
52	    const task: Task = {
53	      ...input,
54	      id: Math.random().toString(36).slice(2),
55	      createdAt: Date.now(),
56	    };
57	    this.tasks.set(task.id, task);
58	
59	    record({
60	      action: 'create',
61	      userId: input.createdBy,
62	      taskId: task.id,
63	      details: `Created task '${task.title}'`,
64	      timestamp: Date.now(),
65	    });
66	
67	    return task;
68	  }
69	
70	  getTask(id: string): Task | null {
71	    return this.tasks.get(id) ?? null;
72	  }
73	
74	  updateStatus(id: string, newStatus: Task['status']): Task | null {
